import React, { useState, useEffect, useRef } from "react";
import {
  AppBar,
  Toolbar,
  IconButton,
  Drawer,
  List,
  ListItem,
  ListItemText,
  Box,
  useMediaQuery,
  useTheme,
  Tabs,
  Tab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  Rating,
  TextField,
  Button,
  Avatar,
  Chip,
  CircularProgress,
  Snackbar,
  Alert,
  Grid,
} from "@mui/material";
import { GiHamburgerMenu } from "react-icons/gi";
import { FaTableTennis, FaCloudUploadAlt } from "react-icons/fa";
import { Close, Delete } from "@mui/icons-material";
import CustomButton from "../Components/CustomButton";
import { GoogleLogin } from "@react-oauth/google";
import { jwtDecode } from "jwt-decode";

const GOOGLE_SCRIPT_URL =
  "https://script.google.com/macros/s/AKfycbyS6BlX8nUR9PiLwMrqRh5vYcK9yrlRDJF_Lk6XTq77XK9R-lLzTIgrcFZbyhebop03kA/exec";

const NavBar = () => {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [currentTab, setCurrentTab] = useState(0);
  const [reviewDialogOpen, setReviewDialogOpen] = useState(false);
  const [authDialogOpen, setAuthDialogOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);
  const [feedbackDialog, setFeedbackDialog] = useState({
  open: false,
  message: "",
  severity: "success", // success, error, info, warning
});
  const [hasReviewed, setHasReviewed] = useState(false);

  // Avatar field ("Your Photo")
  const [reviewData, setReviewData] = useState({
    name: "",
    rating: 0,
    comment: "",
    photo: null,
    photoPreview: null,
  });

  // Multiple "Add Photos"
  const [addPhotos, setAddPhotos] = useState([]);
  const [addPhotosPreview, setAddPhotosPreview] = useState([]);
  const addPhotosInputRef = useRef();

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const menuItems = ["Home", "About", "Testimonials", "Gallery and Awards"];

  // Utility: Convert file to base64 for Google Apps Script
  const fileToBase64 = (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result.split(",")[1]);
      reader.onerror = (error) => reject(error);
    });
  };

  // Utility: Convert file array to base64 array
  const filesToBase64Array = async (files) => {
    return Promise.all(
      files.map(async (file) => ({
        base64: await fileToBase64(file),
        name: file.name,
        type: file.type,
      }))
    );
  };

  // Check for review (via email) once the user is set (or Google sign-in)
  useEffect(() => {
    if (user?.email) {
      fetch(`${GOOGLE_SCRIPT_URL}?email=${encodeURIComponent(user.email)}`)
        .then((res) => res.json())
        .then((data) => {
          if (data.hasReview) {
            setHasReviewed(true);
            setReviewDialogOpen(false);
            showFeedbackDialog("Your review has already been shared.", "info");
          } else {
            setHasReviewed(false);
          }
        })
        .catch(() => {});
    }
  }, [user]);

  // Drawer
  const handleDrawerToggle = () => {
    setDrawerOpen(!drawerOpen);
  };

  // Tabs
  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
  };

  const handleMobileMenuItemClick = (index) => {
    setCurrentTab(index);
    setDrawerOpen(false);
  };

  // Add Review button logic
  const handleAddReviewClick = async () => {
    if (user?.email) {
      // Already signed in: check for review
      fetch(`${GOOGLE_SCRIPT_URL}?email=${encodeURIComponent(user.email)}`)
        .then((res) => res.json())
        .then((data) => {
          if (data.hasReview) {
            setHasReviewed(true);
            showFeedbackDialog("Your review has already been shared.", "info");

            setReviewDialogOpen(false);
          } else {
            setHasReviewed(false);
            setReviewDialogOpen(true);
          }
        })
        .catch(() => {});
    } else {
      setAuthDialogOpen(true);
    }
  };

  // Google OAuth Success
const handleGoogleSuccess = (credentialResponse) => {
  try {
    const decoded = jwtDecode(credentialResponse.credential);
    setUser(decoded);
    setReviewData((prev) => ({
      ...prev,
      name: decoded.name || "",
    }));
    setAuthDialogOpen(false);

    // After successful Google sign-in, check for existing review
    fetch(`${GOOGLE_SCRIPT_URL}?email=${encodeURIComponent(decoded.email)}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.hasReview) {
          setHasReviewed(true);
          setReviewDialogOpen(false);
          showFeedbackDialog("Your review has already been shared.", "info");
        } else {
          setHasReviewed(false);
          setReviewDialogOpen(true); // Automatically open review dialog
        }
      })
      .catch(() => {
        setReviewDialogOpen(false);
        showFeedbackDialog("Could not check your review status. Please try again.", "error");
      });

  } catch (error) {
    showFeedbackDialog("Authentication failed. Please try again.", "error");
  }
};


  // Google OAuth Error
  const handleGoogleError = () => {
    showFeedbackDialog("Google authentication failed. Please try again.", "error");
  };

  // Dialog Close
  const handleAuthDialogClose = () => {
    setAuthDialogOpen(false);
  };
  const handleReviewDialogClose = () => {
    setReviewDialogOpen(false);
    setReviewData((prev) => ({
      ...prev,
      photo: null,
      photoPreview: null,
      rating: 0,
      comment: "",
      name: user ? user.name || "" : "",
    }));
    setAddPhotos([]);
    setAddPhotosPreview([]);
  };

  // "Your Photo" (Avatar) Upload
  const handlePhotoUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      if (!file.type.startsWith("image/")) {
        showFeedbackDialog("Please upload an image file", "error");
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        showFeedbackDialog("Please upload an image smaller than 5MB", "error");
        return;
      }
      const reader = new FileReader();
      reader.onload = (e) => {
        setReviewData((prev) => ({
          ...prev,
          photo: file,
          photoPreview: e.target.result,
        }));
      };
      reader.readAsDataURL(file);
    }
  };
  const handleRemovePhoto = () => {
    setReviewData((prev) => ({
      ...prev,
      photo: null,
      photoPreview: null,
    }));
  };

  // "Add Photos" (Multiple)
  const handleAddPhotosUpload = (event) => {
    const files = Array.from(event.target.files);
    const validFiles = files.filter(
      (file) =>
        file.type.startsWith("image/") &&
        file.size <= 5 * 1024 * 1024 &&
        !addPhotos.find((f) => f.name === file.name)
    );
    if (validFiles.length < files.length) {
      showFeedbackDialog("Some files were not images or were over 5MB.", "warning");
    }
    setAddPhotos((prev) => [...prev, ...validFiles]);
    validFiles.forEach((file) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        setAddPhotosPreview((prev) => [...prev, e.target.result]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleRemoveAddPhoto = (index) => {
    setAddPhotos((prev) => prev.filter((_, i) => i !== index));
    setAddPhotosPreview((prev) => prev.filter((_, i) => i !== index));
  };

  // Snackbar utilities
 const showFeedbackDialog = (message, severity = "success") => {
  setFeedbackDialog({ open: true, message, severity });
};
const handleFeedbackDialogClose = () => {
  setFeedbackDialog((prev) => ({ ...prev, open: false }));
};

  // Input Change
  const handleInputChange = (field, value) => {
    setReviewData((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  // Submit Review
  const handleReviewSubmit = async () => {
    if (hasReviewed) {
      showFeedbackDialog("Your review has already been shared.", "info");
      setReviewDialogOpen(false);
      return;
    }
    if (reviewData.rating === 0) {
      showFeedbackDialog("Please provide a rating", "error");
      return;
    }
    if (!reviewData.name.trim()) {
      showFeedbackDialog("Please enter your name", "error");
      return;
    }

    setLoading(true);

    try {
      const reviewPayload = {
        name: reviewData.name,
        rating: reviewData.rating,
        comment: reviewData.comment,
        email: user?.email || "Unknown",
        timestamp: new Date().toISOString(),
      };
      // Avatar
      if (reviewData.photo) {
        reviewPayload.photo = await fileToBase64(reviewData.photo);
        reviewPayload.photoName = reviewData.photo.name;
        reviewPayload.photoType = reviewData.photo.type;
      }
      // Add Photos
      if (addPhotos.length > 0) {
        reviewPayload.addPhotos = await filesToBase64Array(addPhotos);
      }
      // Submit
      await fetch(GOOGLE_SCRIPT_URL, {
        method: "POST",
        mode: "no-cors",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(reviewPayload),
      });
      showFeedbackDialog(
        "Thank you for your review! It has been submitted successfully."
      );
      handleReviewDialogClose();
      setHasReviewed(true);
    } catch (error) {
      showFeedbackDialog("Failed to submit review. Please try again.", "error");
    } finally {
      setLoading(false);
    }
  };

  // Drawer contents, unchanged
  const drawerContent = (
    <Box
      sx={{
        width: 280,
        height: "100%",
        background:
          "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        padding: 2,
      }}
    >
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <FaTableTennis className="text-orange-500 text-2xl" />
          <span className="font-in font-bold text-white">BT's TT Academy</span>
        </Box>
        <IconButton onClick={handleDrawerToggle} sx={{ color: "white" }}>
          <Close />
        </IconButton>
      </Box>
      <List>
        {menuItems.map((item, index) => (
          <ListItem
            key={item}
            component="button"
            onClick={() => handleMobileMenuItemClick(index)}
            sx={{
              border:
                currentTab === index
                  ? "1px solid #FF9800"
                  : "1px solid rgba(255,255,255,0.1)",
              borderRadius: "8px",
              marginBottom: 1,
              background:
                currentTab === index
                  ? "rgba(255,165,0,0.2)"
                  : "rgba(255,255,255,0.05)",
            }}
          >
            <ListItemText
              primary={item}
              sx={{
                color: currentTab === index ? "#FF9800" : "white",
                "& .MuiListItemText-primary": {
                  fontFamily: "'AlanSans', sans-serif",
                  fontWeight: currentTab === index ? 600 : 500,
                },
              }}
            />
          </ListItem>
        ))}
      </List>
      <Box sx={{ padding: 2 }}>
        <CustomButton
          rating
          size="small"
          onClick={handleAddReviewClick}
          fullWidth
          text="Add Review"
        />
      </Box>
    </Box>
  );

  return (
    <>
      <div
        position="static"
        sx={{
          background: "transparent",
          boxShadow: "none",
          backdropFilter: "blur(10px)",
          background: "rgba(0,0,0,0.1)",
        }}
      >
        <Toolbar sx={{ justifyContent: "space-between", padding: "8px 0" }}>
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <FaTableTennis className="text-white text-3xl" />
          </Box>
          <Box
            sx={{
              display: { xs: "none", md: "flex" },
              alignItems: "center",
              gap: 2,
            }}
          >
            <Box
              sx={{
                background: "rgba(0,0,0,0.1)",
                borderRadius: "25px",
                border: "1px solid rgba(255,255,255,0.1)",
                padding: "4px",
              }}
            >
              <Tabs
                value={currentTab}
                onChange={handleTabChange}
                sx={{
                  minHeight: "40px",
                  "& .MuiTabs-indicator": {
                    backgroundColor: "#f97316",
                    height: "100%",
                  },
                  "& .MuiTab-root": {
                    color: "rgba(255,255,255,0.7)",
                    fontFamily: "'AlanSans', sans-serif",
                    fontWeight: 500,
                    fontSize: "14px",
                    textTransform: "none",
                    minHeight: "32px",
                    margin: "0 2px",
                    minWidth: "auto",
                    zIndex: 1,
                    "&.Mui-selected": {
                      color: "white",
                      fontWeight: 600,
                    },
                    "&:hover": {
                      color: "#E2DBD1",
                    },
                  },
                }}
              >
                {menuItems.map((item) => (
                  <Tab key={item} label={item} />
                ))}
              </Tabs>
            </Box>
            <CustomButton
              rating
              size="small"
              text="Add Review"
              onClick={handleAddReviewClick}
            />
          </Box>
          <IconButton
            sx={{
              display: { xs: "flex", md: "none" },
              color: "white",
              background: "rgba(0,0,0,0.1)",
              border: "1px solid rgba(255,255,255,0.1)",
              "&:hover": {
                background: "rgba(255,165,0,0.2)",
              },
            }}
            onClick={handleDrawerToggle}
          >
            <GiHamburgerMenu />
          </IconButton>
        </Toolbar>
      </div>
      <Drawer
        variant="temporary"
        anchor="right"
        open={drawerOpen}
        onClose={handleDrawerToggle}
        ModalProps={{ keepMounted: true }}
        sx={{
          display: { xs: "block", md: "none" },
          "& .MuiDrawer-paper": {
            boxSizing: "border-box",
            width: 280,
            border: "none",
            background: "transparent",
          },
        }}
      >
        {drawerContent}
      </Drawer>
      {/* Auth Dialog */}
      <Dialog
        open={authDialogOpen}
        onClose={handleAuthDialogClose}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
            textAlign: "center",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography
            variant="h6"
            sx={{ fontFamily: "'AlanSans', sans-serif" }}
          >
            Sign In to Continue
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ padding: 3 }}>
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
            }}
          >
            <FaTableTennis className="text-orange-500 text-4xl" />
            <Typography
              variant="h6"
              sx={{ fontFamily: "'AlanSans', sans-serif" }}
            >
              BT's TT Academy
            </Typography>
            <Typography
              variant="body2"
              sx={{ color: "rgba(255,255,255,0.7)", mb: 2 }}
            >
              Sign in with Google to add your review and share your experience
              with our academy.
            </Typography>
            <Box sx={{ width: "100%", maxWidth: "200px" }}>
              <GoogleLogin
                onSuccess={handleGoogleSuccess}
                onError={handleGoogleError}
                size="large"
                width="100%"
                shape="circle"
              />
            </Box>
          </Box>
        </DialogContent>
        <DialogActions
          sx={{
            padding: 2,
            justifyContent: "center",
            borderTop: "1px solid rgba(255,255,255,0.1)",
          }}
        >
          <Button
            onClick={handleAuthDialogClose}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
      {/* Review Dialog */}
      <Dialog
        open={reviewDialogOpen}
        onClose={handleReviewDialogClose}
        maxWidth="sm"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
          },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid rgba(255,255,255,0.1)" }}>
          <Typography
            variant="h6"
            sx={{ fontFamily: "'AlanSans', sans-serif" }}
          >
            Add Your Review
          </Typography>
          {user && (
            <Typography
              variant="body2"
              sx={{ color: "rgba(255,255,255,0.7)", mt: 0.5 }}
            >
              Signed in as: {user.name || user.email}
            </Typography>
          )}
        </DialogTitle>
        <DialogContent sx={{ padding: 3 }}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
            {/* Name Field */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Name *
              </Typography>
              <TextField
                fullWidth
                value={reviewData.name}
                onChange={(e) => handleInputChange("name", e.target.value)}
                placeholder="Enter your name"
                variant="outlined"
                disabled={!!user}
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: user
                        ? "rgba(255,255,255,0.2)"
                        : "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                    "& .MuiInputBase-input.Mui-disabled": {
                      WebkitTextFillColor: "rgba(255,255,255,0.7)",
                    },
                  },
                }}
              />
              {user && (
                <Typography
                  variant="caption"
                  sx={{
                    color: "rgba(255,255,255,0.5)",
                    mt: 1,
                    display: "block",
                  }}
                >
                  Name is taken from your Google profile
                </Typography>
              )}
            </Box>
            {/* Avatar Photo Upload */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Photo (Avatar, Optional)
              </Typography>
              {reviewData.photoPreview ? (
                <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                  <Avatar
                    src={reviewData.photoPreview}
                    sx={{ width: 80, height: 80, border: "2px solid #FF9800" }}
                  />
                  <Box>
                    <Chip
                      label={reviewData.photo.name}
                      variant="outlined"
                      sx={{
                        color: "white",
                        borderColor: "rgba(255,255,255,0.3)",
                      }}
                    />
                    <Button
                      onClick={handleRemovePhoto}
                      sx={{
                        color: "#FF9800",
                        ml: 1,
                        "&:hover": { background: "rgba(255,152,0,0.1)" },
                      }}
                    >
                      Remove
                    </Button>
                  </Box>
                </Box>
              ) : (
                <Box
                  sx={{
                    border: "2px dashed rgba(255,255,255,0.3)",
                    borderRadius: "8px",
                    padding: 3,
                    textAlign: "center",
                    cursor: "pointer",
                    "&:hover": {
                      borderColor: "#FF9800",
                      background: "rgba(255,152,0,0.05)",
                    },
                  }}
                  onClick={() =>
                    document.getElementById("photo-upload").click()
                  }
                >
                  <input
                    id="photo-upload"
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoUpload}
                    style={{ display: "none" }}
                  />
                  <FaCloudUploadAlt
                    style={{
                      fontSize: "2rem",
                      color: "#FF9800",
                    }}
                  />
                  <Typography
                    variant="body2"
                    sx={{ color: "rgba(255,255,255,0.7)" }}
                  >
                    Click to upload a photo
                  </Typography>
                  <Typography
                    variant="caption"
                    sx={{ color: "rgba(255,255,255,0.5)" }}
                  >
                    PNG, JPG, JPEG (Max 5MB)
                  </Typography>
                </Box>
              )}
            </Box>
            {/* Add Photos Multiple */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Add Photos (Optional, Multiple)
              </Typography>
              <input
                multiple
                type="file"
                accept="image/*"
                style={{ display: "none" }}
                ref={addPhotosInputRef}
                onChange={handleAddPhotosUpload}
              />
              <Box
                sx={{
                  border: "2px dashed rgba(255,255,255,0.3)",
                  borderRadius: "8px",
                  padding: 3,
                  textAlign: "center",
                  cursor: "pointer",
                  minHeight: "60px",
                  "&:hover": {
                    borderColor: "#FF9800",
                    background: "rgba(255,152,0,0.05)",
                  },
                  marginBottom: 2,
                }}
                onClick={() => {
                  addPhotosInputRef.current.click();
                }}
              >
                <FaCloudUploadAlt
                  style={{
                    fontSize: "2rem",
                    color: "#FF9800",
                  }}
                />
                <Typography
                  variant="body2"
                  sx={{ color: "rgba(255,255,255,0.7)" }}
                >
                  Click to upload extra photos
                </Typography>
                <Typography
                  variant="caption"
                  sx={{ color: "rgba(255,255,255,0.5)" }}
                >
                  PNG, JPG, JPEG (Max 5MB each)
                </Typography>
              </Box>
              {/* Grid of thumbnails for addPhotos */}
              <Grid container spacing={2}>
                {addPhotosPreview.map((preview, idx) => (
                  <Grid item key={idx}>
                    <Box
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "center",
                      }}
                    >
                      <Avatar
                        src={preview}
                        sx={{
                          width: 60,
                          height: 60,
                          border: "2px solid #FF9800",
                          marginBottom: 1,
                        }}
                      />
                      <Chip
                        label={addPhotos[idx]?.name || ""}
                        variant="outlined"
                        sx={{
                          color: "white",
                          borderColor: "rgba(255,255,255,0.3)",
                          marginBottom: 1,
                        }}
                      />
                      <IconButton
                        sx={{ color: "#FF9800" }}
                        onClick={() => handleRemoveAddPhoto(idx)}
                      >
                        <Delete />
                      </IconButton>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Box>
            {/* Rating */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Rating *
              </Typography>
              <Rating
                value={reviewData.rating}
                onChange={(e, newValue) =>
                  handleInputChange("rating", newValue)
                }
                size="large"
                sx={{
                  color: "#FF9800",
                  "& .MuiRating-iconFilled": {
                    color: "#FF9800",
                  },
                }}
              />
            </Box>
            {/* Comment */}
            <Box>
              <Typography gutterBottom sx={{ fontWeight: 500 }}>
                Your Review
              </Typography>
              <TextField
                multiline
                rows={4}
                fullWidth
                value={reviewData.comment}
                onChange={(e) => handleInputChange("comment", e.target.value)}
                placeholder="Share your experience with BT's TT Academy..."
                variant="outlined"
                sx={{
                  "& .MuiOutlinedInput-root": {
                    color: "white",
                    "& fieldset": {
                      borderColor: "rgba(255,255,255,0.2)",
                    },
                    "&:hover fieldset": {
                      borderColor: "rgba(255,255,255,0.4)",
                    },
                    "&.Mui-focused fieldset": {
                      borderColor: "#FF9800",
                    },
                  },
                }}
              />
            </Box>
          </Box>
        </DialogContent>
        <DialogActions
          sx={{ padding: 3, borderTop: "1px solid rgba(255,255,255,0.1)" }}
        >
          <Button
            onClick={handleReviewDialogClose}
            disabled={loading}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover:not(:disabled)": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleReviewSubmit}
            variant="contained"
            disabled={
              !reviewData.name.trim() ||
              reviewData.rating === 0 ||
              loading ||
              hasReviewed
            }
            sx={{
              background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
              "&:hover:not(:disabled)": {
                background: "linear-gradient(45deg, #E65100 30%, #BF360C 90%)",
              },
              "&:disabled": {
                background: "rgba(255,255,255,0.1)",
                color: "rgba(255,255,255,0.3)",
              },
              minWidth: "120px",
            }}
          >
            {loading ? <CircularProgress size={24} /> : "Submit Review"}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={feedbackDialog.open}
        onClose={handleFeedbackDialogClose}
        maxWidth="xs"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background:
              "linear-gradient(135deg, rgba(0,0,0,0.95) 0%, rgba(50,50,50,0.98) 100%)",
            color: "white",
            borderRadius: "12px",
            textAlign: "center",
            padding: 2,
          },
        }}
      >
        <DialogTitle>
          {feedbackDialog.severity === "error" && (
            <Typography variant="h6" sx={{ color: "#FF5252", mb: 1 }}>
              Error
            </Typography>
          )}
          {feedbackDialog.severity === "success" && (
            <Typography variant="h6" sx={{ color: "#4CAF50", mb: 1 }}>
              Success
            </Typography>
          )}
          {feedbackDialog.severity === "info" && (
            <Typography variant="h6" sx={{ color: "#FF9800", mb: 1 }}>
              Info
            </Typography>
          )}
          {feedbackDialog.severity === "warning" && (
            <Typography variant="h6" sx={{ color: "#FFC107", mb: 1 }}>
              Warning
            </Typography>
          )}
        </DialogTitle>
        <DialogContent>
          <Typography variant="body1">{feedbackDialog.message}</Typography>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleFeedbackDialogClose}
            sx={{
              color: "rgba(255,255,255,0.7)",
              "&:hover": {
                color: "white",
                background: "rgba(255,255,255,0.1)",
              },
            }}
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default NavBar;
